"""Full-span expression decisions for the second VI contextual package."""
from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parents[1]/'content/sources/wrk_voltaire_micromegas'
read=lambda f:json.loads((P/f).read_text())
h=lambda v:hashlib.sha256(json.dumps(v,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
digest=lambda f:hashlib.sha256((P/f).read_bytes()).hexdigest()
def write(f,d):(P/f).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
units=read('unit-plan.json')['units'];tokens=read('chapter-06-inventory.json')['tokens'];base=read('chapter-06-context-review-04.json');packet=read('chapter-06-context-packet-04.json')
considered={ (o['unit'],o['start'],o['end'])for row in [*base['items'],*base['holds']]for o in row['sourceOccurrences']}
items=[]
def expr(key,phrase,occ,meaning,low,middle,options,advanced,note,target='new_expression_meaning',nounAgreement=None):
 uses=[]
 for unit in occ:
  text=units[unit-1]['text'];start=text.index(phrase);uses.append({'chapter':6,'unit':unit,'start':start,'end':start+len(phrase),'text':phrase})
 component=[t for t in tokens if any(t['unit']==o['unit']and t['start']>=o['start']and t['end']<=o['end']for o in uses)]
 if not any((t['unit'],t['start'],t['end'])in considered for t in component):return
 qs=[{'band':'1-3','context':units[uses[0]['unit']-1]['text'],'targetText':phrase,'question':'What does the highlighted phrase mean here?','answer':meaning,'choices':[meaning,*low]},{'band':'4-5','context':middle,'question':'Complétez la phrase.','answer':options[0],'choices':options},{'band':'6-8','context':advanced,'question':'Quelle expression convient ?','answer':options[0],'choices':options}]
 item={'key':key,'surfacePattern':phrase,'meaning':meaning,'sourceOccurrences':uses,'componentTokens':[{k:t[k]for k in ['unit','start','end','text','form']}for t in component],'questions':qs,'questionSha256':h(qs),'identityTarget':target,'reviewNote':note,'status':'offline_full_span_three_band_review_recorded_unpublished'}
 if nounAgreement:item['middleNounAgreement']=nounAgreement
 items.append(item)

expr('quart_de_cercle','quart de cercle',[157],'quadrant; an instrument for measuring angles',['drawing compass','wooden hammer','wall barometer'],'L’instrument gradué en arc de quatre-vingt-dix degrés pour mesurer des angles est un ___.',['quart de cercle','compas de dessin','marteau de bois','baromètre mural'],'Quelle locution nominale désigne l’instrument gradué en quart de circonférence qui mesure des angles ?','The Chapter V quarts de cercle bank and its primary Académie 1762 quart evidence were re-read. This is the singular form of the same angular measuring instrument, with pinnules for sighting, not a new fraction sense. All four complete noun phrases are masculine singular and fit un; angular graduation selects the quadrant. Share the earlier expression meaning with a distinct singular surface and its own bank.','share_earlier_expression_meaning:chapter-05-expression-review.json:quarts_de_cercle','masculine singular noun phrases; all choices fit un')
if any(i['key']=='quart_de_cercle'for i in items):
 q=next(i for i in items if i['key']=='quart_de_cercle');q.update(earlierDecisionFile='chapter-05-expression-review.json',earlierDecisionKey='quarts_de_cercle',earlierDecisionFileSha256=digest('chapter-05-expression-review.json'))
expr('juste_ciel','juste Ciel',[158],'good heavens!; an exclamation of astonishment',['hello!','thank you!','goodbye!'],'Le nain manifeste sa stupeur en s’écriant « ___ ».',['juste Ciel','bonjour','merci beaucoup','au revoir'],'Quelle expression du récit est une invocation exclamative marquant l’étonnement ?','The dwarf reacts to the unexpectedly exact measurement with a conventional invocation of providence. The published divine Ciel bank and literal just/exact/tight meanings were inspected, but the whole exclamation carries the surprise function. All four options are complete formulae; astonishment rather than greeting, thanks or farewell selects juste Ciel. Final reconciliation must avoid adding duplicate Ciel component mastery for this span.')
# Reuse the already reviewed singular abstract-large phrase when grand enters this range.
oldfile='chapter-06-expression-review-03.json';old=next(i for i in read(oldfile)['items']if i['key']=='l_infiniment_grand')
if any((t['unit'],t['start'],t['end'])in considered for t in old['componentTokens']):
 item=dict(old);item.update(earlierFile=oldfile,earlierKey=old['key'],earlierFileSha256=digest(oldfile),reviewNote='The exact l’infiniment grand bank was re-read for grand at 164:147. The whole phrase is an abstract domain of infinitely large dimensions, not physical grand in tree/companion or intense grand respect. Reuse the previous full-span meaning and its three bands without duplicate component mastery; all complete middle noun choices remain masculine singular.');items.append(item)
expr('de_son_long','de son long',[160],'at full length; stretched out',['in detail','very briefly','in great haste'],'Il étendit entièrement son corps : il se coucha ___.',['de son long','en détail','en un instant','à toute vitesse'],'Quelle locution exprime la position d’un corps étendu sur toute sa longueur ?','The giant stretches his body out for measurement; long is not the published detailed-narrative au long sense. The whole posture phrase explains the source, and each alternative fits se coucha as an adverbial modifier; bodily extent rather than manner of narration, speed or short duration selects de son long. No detailed-explanation mastery is transferred.')
expr('me_garderai_bien_de','me garderai bien d’',[161],'will take care not to call; will avoid naming',['will be eager to name','will forget to name','will decide to name'],'Je veux éviter de nommer cet endroit : je ___appeler cet endroit par son nom.',['me garderai bien d’','m’empresserai d’','négligerai d’','déciderai d’'],'Quelle construction signifie prendrai soin de ne pas nommer cet endroit ?','Se garder bien de plus infinitive means deliberate avoidance, not keeping an object. The complete inflected se garder bien de source phrase carries deliberate avoidance; appeler follows as its separately reviewed naming infinitive. All four prefixes attach directly to appeler cet endroit par son nom and distinguish careful avoidance from eagerness, neglect and decision. The source narrator’s unnamed anatomy is preserved without invention.')
expr('a_cause_de','à cause de',[161],'because of; on account of',['despite','without','in addition to'],'Il refuse de nommer l’endroit en raison de son respect : il le tait ___ son respect pour les dames.',['à cause de','malgré','sans','en plus de'],'Quelle locution prépositive indique la raison de ce refus ?','À cause de introduces respect as the reason for declining to name the body part. The noun cause bank and earlier work phrase decisions were compared, but the full causal connection is prepared so the isolated noun question cannot suggest an effect. All four alternatives attach directly to son respect; the explicitly causal clue selects à cause de.')
expr('pieds_de_roi','pieds de roi',[162],'royal feet; historical French units of length',['litres of wine','hammer blows','dance steps'],'Le récit exprime la hauteur du géant dans les anciennes unités françaises de longueur appelées ___.',['pieds de roi','litres de vin','coups de marteau','pas de danse'],'Quelle locution nominale désigne ici les unités françaises historiques qui servent à mesurer cette hauteur ?','The earlier pieds length-measure plan and primary source evidence were re-read; pieds de roi is the specified historical foot unit, not a king’s anatomical feet. Retain the earlier measurement sense as a whole phrase with a contextual bank; no modern metric conversion is asserted. All four phrases are masculine plural and fit the unchanged called-units stem; length-unit meaning selects pieds de roi.','share_earlier_length_measure_meaning:chapter-01-identity-plan.json:pieds_length_measure','masculine plural complete noun phrases')
if any(i['key']=='pieds_de_roi'for i in items):
 q=next(i for i in items if i['key']=='pieds_de_roi');q.update(earlierDecisionFile='chapter-01-identity-plan.json',earlierDecisionKey='pieds_length_measure',earlierDecisionFileSha256=digest('chapter-01-identity-plan.json'))
oldfile='chapter-06-expression-review-02.json';old=next(i for i in read(oldfile)['items']if i['key']=='en_effet')
if any((t['unit'],t['start'],t['end'])in considered for t in old['componentTokens']):
 item=dict(old);item.update(earlierFile=oldfile,earlierKey=old['key'],earlierFileSha256=digest(oldfile),reviewNote='The two effet noun-shaped tokens at 162:95 and 165:82 belong to the previously reviewed en effet confirmation phrase. The exact three-band bank was re-read; indeed confirms the calculated height and the existence claim, rather than naming a physical effect or a cause. Reuse that full-span bank without any duplicate effect-word mastery.');items.append(item)
expr('en_toute_surete','en toute sûreté',[165],'with complete certainty; with assurance',['in great haste','in strict secrecy','with hesitation'],'Il peut tenir cette affirmation pour certaine, sans aucun doute : il peut la croire ___.',['en toute sûreté','en toute hâte','en grand secret','avec hésitation'],'Quelle locution du récit indique qu’on peut croire quelque chose avec assurance ?','The philosopher assures the giant that still smaller intelligent beings exist. En toute sûreté modifies croire with epistemic certainty, not bodily protection or a secure locked place. The published toute determiner and absence of a sûreté bank were checked, but the full adverbial phrase supplies the source meaning. All four phrases fit croire as manner modifiers; no doubt rather than haste, secrecy or hesitation selects en toute sûreté.')
# Full-span items are authored as their components enter the reviewed range.
common={k:packet[k]for k in ['version','workId','chapter','sourceSha256','unitPlanSha256','inventorySha256']}
record={**common,'status':'offline_full_span_review_unpublished','summary':{'reviewedExpressionForms':len(items),'reviewedQuestionBands':len(items)*3,'newExpressionForms':sum(not i.get('earlierFile')for i in items),'newQuestionBands':sum(3 for i in items if not i.get('earlierFile')),'reusedEarlierQuestionBands':sum(3 for i in items if i.get('earlierFile'))},'items':items}
write('chapter-06-expression-review-04.json',record)
print(json.dumps(record['summary']))
